insert into public.master_requirements (id,title,statement,source_basis,iat_coverage,evidence,sa_output,moo_output,platform_req,data_entities,escalation_rule,priority,sort) values
('MR-01','Project objective: validated actionable MOO','Create one integrated, evidence-based operating framework linking CDRRMO institutional functions and EOC incident coordination.','Inception Report Objectives 1–5; IAT v1.1 purpose/use','All 140 indicators (125 core in Parts A–B; 15 interface in Part C)','Validated evidence register; scored baseline; priority gaps','Executive Summary; methodology; consolidated findings; priority actions','Integrated MOO architecture; procedures, standards, roles, forms and update mechanism','Role-based assessment workflow; evidence-first scoring; traceability view','Assessment cycle; evidence; scores; gaps; actions; MOO traceability; document versions','Applies to the whole assessment','Critical',1),
('MR-02','Functional Area 1','Define mandate, organization, authority, delegation, roles, coordination and accountability.','MOO Functional Area 1; A1, A2, A10','A1.1–A1.8; A2.1–A2.10; A10.1–A10.3','Legal instruments, organogram, plantilla, rosters, MOAs, reporting records, skills inventory','Governance/institutional findings','Ch.1–2; Ch.9 partnerships; role/JD annexes','Governance module; role matrix; approval workflow','organizations; offices; positions; authorities; partnerships; declarations; skills_inventory','High when mandatory legal/role gaps score below 3','High',2),
('MR-03','Functional Area 2','Maintain current multi-hazard risk intelligence, prevention/mitigation and risk-informed planning.','MOO Functional Area 2; A3, A5; Part C C1–C3','A3.1–A3.7; A5.1–A5.9; interface C1.1–C1.4, C2.1–C2.3, C3.1–C3.3','Plans, hazard maps, CDRA, GIS/data records, critical-facility dependency map, dataset version dates; lead-office records for Part C','Risk and planning baseline; Part C interface results','Ch.3 Planning; Ch.7 Knowledge Management','GIS/risk dashboard; document/version control; failure-chain view','plans; hazards; risk_scenarios; gis_layers; datasets; critical_facilities; facility_dependencies','Risk-informed prioritization','High',3),
('MR-04','Functional Area 3','Establish preparedness, contingency planning, capacity development, drills and readiness standards.','MOO Functional Area 3; A3, A7, B7; Part C C5','A3.3–A3.6; A7.1–A7.9; B7.2–B7.6; interface C5.1','CPs, PSCP, training, refresher and drill records, EC audits, stock records, welfare-check drills','Preparedness capacity and readiness gaps','Ch.3 Planning; Ch.4; Ch.6 Capacity; EOC Ch.8–9','Preparedness dashboard; training/exercise calendar; refresher tracking','plans; training; exercises; evacuation_centers; inventories; welfare_checks','High for untested mandatory readiness','High',4),
('MR-05','Functional Area 4','Define EOC activation/deactivation, incident management, ICS interface, escalation, transition and anticipatory action.','MOO Functional Area 4; B1, B4, B7.1, A8; A1.8; Part C C4','A1.8; A8.1–A8.9; B1.1–B1.5; B4.1–B4.2; B7.1; interface C4.1–C4.4','ICS EO, IMT roster, activation matrix/logs, EOC organogram and roster with alternates, approved EOC SOPs, PDRA records, AA protocols, sector AA plans','EOC/response readiness baseline','Ch.4 Response; EOC Ch.1–2; EOC Ch.7','Activation wizard; operational-period workflow; ICS/EOC role view; AA protocol checklist','activation_levels; activation_events; incidents; imt_rosters; aa_protocols','Immediate escalation for mandatory activation/ICS/AA gaps','Critical',5),
('MR-06','Functional Area 5','Operate hazard monitoring, warning thresholds, last-mile dissemination, emergency communications and public information.','MOO Functional Area 5; A6, B3','A6.1–A6.7; B3.1–B3.6','EWS logs, warning matrix, test logs, comms inventory, directory, declaration/AA advisory templates','Warning/communications findings','Ch.4; EOC Ch.3–4; EOC Ch.5','Warning composer; dissemination log; channel status','warning_systems; thresholds; messages; channels; communication_assets; network_tests; advisory_templates','Life-safety priority; weight-3 mandatory gaps','Critical',6),
('MR-07','Functional Area 6','Maintain situational awareness, information management, GIS/COP, SitReps and reporting flows.','MOO Functional Area 6; B5, A5, A10','A5.1–A5.9; A10.3–A10.8; B5.1–B5.7','GIS layers, SitReps, logs, monitoring records, reports, 45-day RA 12287 reports, citizen-report intake logs','Information-system and reporting baseline','Ch.7; EOC Ch.5–6','Common Operating Picture; reporting workflow; audit trail; verified citizen-report intake','sit_reps; cop_layers; event_logs; reports; hazard_feeds; citizen_reports; declaration_reports','Data quality/completeness and timeliness','High',7),
